// Approved maintenance window (UTC). Days: 0 = Sunday ... 6 = Saturday.
let ChangeWindowDays = dynamic([6, 0]);
let ChangeWindowStartHour = 1;
let ChangeWindowEndHour = 6;
// Set true to alert only on changes made outside the window.
let OnlyOutsideChangeWindow = false;
Nutanix_CL
| where Category in ("audit", "event")
| where tolower(SourceEntityType) has_any ("lcm", "certificate", "firmware")
    or Message has_any ("LCM", "life cycle", "lifecycle", "firmware", "BMC", "BIOS", "upgrade", "ssl certificate", "certificate", "ca chain")
| extend Day = toint(dayofweek(TimeGenerated) / 1d), Hour = hourofday(TimeGenerated)
| extend OutsideChangeWindow = not(Day in (ChangeWindowDays) and Hour >= ChangeWindowStartHour and Hour < ChangeWindowEndHour)
| where not(OnlyOutsideChangeWindow) or OutsideChangeWindow
| project-away Day, Hour
| extend AccountCustomEntity = ActorUser, HostCustomEntity = NutanixClusterName, IpCustomEntity = SourceIp
